T={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
def trans(S, rot, flip):
    pts=[]
    for r,c in S:
        if flip: c=-c
        for _ in range(rot): r,c=c,-r
        pts.append((r,c))
    mr=min(r for r,c in pts); mc=min(c for r,c in pts)
    return {(r-mr,c-mc) for r,c in pts}
Ts=[trans(T,k,f) for k in range(4) for f in range(2)]
components={5:{(0,1),(1,0),(1,1)},6:{(0,0),(1,0),(1,2)},3:{(0,0),(1,1),(2,1)},7:{(0,0),(1,1)},2:{(0,0),(0,1)},9:{(0,2),(1,0)},8:{(0,0),(1,0),(2,0)}}
# compare whether shape component is subset of T transform after translation, normalized component bbox
for col,S in components.items():
  opts=[]
  for i,U in enumerate(Ts):
    h=max(r for r,c in U)+1; w=max(c for r,c in U)+1
    for dr in range(h):
      for dc in range(w):
        if {(r+dr,c+dc) for r,c in S}<=U: opts.append(i)
  print(col,sorted(set(opts)), bool(opts))

